import json, sys
baseline = json.load(open('baseline-packages.json'))
after = json.load(sys.stdin)

def extract(data):
    result = {}
    for p in data['projects']:
        name = p['path'].split('/')[-1]
        for fw in p['frameworks']:
            for pkg in fw['topLevelPackages']:
                result.setdefault(name, {})[pkg['id']] = pkg['resolvedVersion']
    return result

b = extract(baseline)
a = extract(after)
if b == a:
    print('✅ Package versions match exactly — conversion is version-neutral.')
else:
    print('❌ Differences detected:')
    for proj in sorted(set(list(b.keys()) + list(a.keys()))):
        bp = b.get(proj, {}); ap = a.get(proj, {})
        for pkg in sorted(set(list(bp.keys()) + list(ap.keys()))):
            if bp.get(pkg) != ap.get(pkg):
                print(f'  {proj}: {pkg} {bp.get(pkg)} -> {ap.get(pkg)}')
"

